// TypeScript Version: 4.1

import Uint64 = require( '@stdlib/number/uint64/ctor' );

/**
* Parses a string representation of a 64-bit unsigned integer.
*
* @param str - string representation of a 64-bit unsigned integer
* @param radix - radix (base) to use for string conversion (2-36)
* @returns 64-bit unsigned integer
*
* @example
* var a = parseUint64( '1234' );
* // returns <Uint64>[ 1234n ]
*
* a = parseUint64( '0xffffffffffffffff' );
* // returns <Uint64>[ 18446744073709551615n ]
*
* a = parseUint64( '123abcxyz', 36 );
* // returns <Uint64>[ 2984992324091n ]
*/
declare function parseUint64( str: string, radix?: number ): Uint64;


// EXPORTS //

export = parseUint64;
